//! Gold: `incremental_corpus` is 1:1 with the live
//! `harness/electronics/incremental_corpus.py`.
//!
//! `tests/fixtures/gold/incremental_corpus_v1.json` was generated by
//! `scripts/gold_incremental_corpus.py` — `build` cases materialise a fixture
//! tree (snapshot bytes carry `$ROOT` path templates and a `$DIGEST`
//! placeholder, substituted on BOTH sides after materialisation, which makes
//! the snapshot's evidence digest a live differential check against Python's
//! `hashlib`) and run `build_incremental_corpus_registry` end to end; kernel
//! cases call the pure readers. Absolute paths normalise to `$ROOT`.
//!
//! The cases pin the traps the reader exists for: sources must still hash and
//! size as intaked ("changed after intake"), the snapshot's own digest and
//! document count are enforced, `source_path` must stay under the PDF root
//! and be a regular file, directory vendor prefixes invent alias stems
//! (`ti.com/ti_mcu.pdf` -> `ti_ti_mcu`) that join ground truth like exact
//! stems, bindings contribute `record_ids` and `manifested_opn` memberships,
//! ambiguous stems (one stem, two digests) join nothing, `_`-prefixed
//! validated subdirectories are skipped, `_part_key` keeps `0` and `False`
//! (only `None` is absent — unlike `corpus`), and `_summary` has no stem
//! vendor fallback.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::cast_possible_truncation,
    clippy::doc_markdown,
    clippy::panic,
    reason = "gold tests assert on their own fixtures"
)]

use std::fs;
use std::path::{Path, PathBuf};

use serde_json::Value;

use dw_recon::incremental_corpus::{build_incremental_corpus_registry, part_key, summary};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/incremental_corpus_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

/// The generator materialises at a FIXED root: the snapshot's file hash and
/// embedded evidence digest cover root-containing bytes, so both sides must
/// write at the same path to produce identical digests.
fn temp_root(name: &str) -> PathBuf {
    let root = PathBuf::from(format!("/tmp/gold_inc_corpus_{name}"));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).unwrap();
    fs::canonicalize(&root).unwrap_or(root)
}

fn normalise(value: &mut Value, root: &str) {
    match value {
        Value::String(s) => *s = s.replace(root, "$ROOT"),
        Value::Array(list) => {
            for item in list {
                normalise(item, root);
            }
        }
        Value::Object(map) => {
            for (_, item) in map.iter_mut() {
                normalise(item, root);
            }
        }
        _ => {}
    }
}

fn reissue_digest(registry: &mut Value) {
    if let Some(map) = registry.as_object_mut() {
        map.remove("created_at");
    }
    let core = {
        let mut map = serde_json::Map::new();
        for (key, item) in registry.as_object().into_iter().flatten() {
            if key != "evidence_sha256" {
                map.insert(key.clone(), item.clone());
            }
        }
        Value::Object(map)
    };
    if let Some(map) = registry.as_object_mut() {
        map.insert(
            "evidence_sha256".into(),
            Value::String(dw_recon::corpus::canonical_json_sha256(&core)),
        );
    }
}

/// `$ROOT` path templates, then `$DIGEST` = digest of the materialised core.
fn materialise(data: &[u8], root: &str) -> Vec<u8> {
    let replaced = String::from_utf8(data.to_vec())
        .unwrap()
        .replace("$ROOT", root);
    if !replaced.contains("$DIGEST") {
        return replaced.into_bytes();
    }
    let value: Value = serde_json::from_str(&replaced).unwrap();
    let core = {
        let mut map = serde_json::Map::new();
        for (key, item) in value.as_object().into_iter().flatten() {
            if key != "created_at" && key != "evidence_sha256" {
                map.insert(key.clone(), item.clone());
            }
        }
        Value::Object(map)
    };
    let digest = dw_recon::corpus::canonical_json_sha256(&core);
    replaced.replace("$DIGEST", &digest).into_bytes()
}

fn write_tree(root: &Path, tree: &Value) {
    for entry in tree.as_array().into_iter().flatten() {
        let rel = entry["path"].as_str().unwrap();
        let target = root.join(rel);
        fs::create_dir_all(target.parent().unwrap()).unwrap();
        let bytes: Vec<u8> = entry["bytes"]
            .as_array()
            .unwrap()
            .iter()
            .map(|b| b.as_u64().unwrap() as u8)
            .collect();
        let payload = if entry["subst"].as_bool().unwrap_or(false) {
            materialise(&bytes, &root.display().to_string())
        } else {
            bytes
        };
        fs::write(&target, payload).unwrap();
    }
}

fn compare_error(message: &str, expect: &Value, name: &str) {
    if expect["kind"].as_str() == Some("os") {
        // Missing paths surface as OS errors; only rejection is wire.
        return;
    }
    let want = expect["message"].as_str().unwrap();
    match expect["match"].as_str().unwrap() {
        "exact" => assert_eq!(message, want, "case {name}"),
        "contains" => assert!(message.contains(want), "case {name}: {message}"),
        other => panic!("unknown error match {other}"),
    }
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        match case["kind"].as_str().unwrap() {
            "build" => {
                let root = temp_root(name);
                // The generator always materialises the three roots.
                for key in ["pdfs", "gt", "validated"] {
                    fs::create_dir_all(root.join(key)).unwrap();
                }
                write_tree(&root, &case["input"]["tree"]);
                let config = &case["input"]["config"];
                let rel =
                    |key: &str, default: &str| root.join(config[key].as_str().unwrap_or(default));
                let root_str = root.display().to_string();
                let outcome = build_incremental_corpus_registry(
                    &rel("snapshot", "snapshot.json"),
                    &rel("pdf_root", "pdfs"),
                    &rel("ground_truth_root", "gt"),
                    &rel("validated_root", "validated"),
                );
                match outcome {
                    Ok(registry) => {
                        assert!(
                            case.get("error").is_none_or(Value::is_null),
                            "case {name}: expected error {:?}",
                            case["error"]
                        );
                        let mut got = registry;
                        normalise(&mut got, &root_str);
                        reissue_digest(&mut got);
                        assert_eq!(got, case["expected"], "case {name}");
                    }
                    Err(error) => {
                        let mut message = error.to_string();
                        message = message.replace(&root_str, "$ROOT");
                        assert!(
                            !case["expected"].is_object(),
                            "case {name}: unexpected {message}"
                        );
                        compare_error(&message, &case["error"], name);
                    }
                }
                let _ = fs::remove_dir_all(&root);
            }
            "part_key" => {
                let got = part_key(&case["input"]["value"]);
                let expected: Option<String> =
                    serde_json::from_value(case["expected"].clone()).unwrap();
                assert_eq!(got, expected, "case {name}");
            }
            "summary" => {
                let root = temp_root("sum"); // generator: /tmp/gold_inc_corpus_sum
                let rel_path = case["input"]["rel_path"].as_str().unwrap();
                let target = root.join(rel_path);
                fs::create_dir_all(target.parent().unwrap()).unwrap();
                let payload: Vec<u8> = case["input"]["payload"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|b| b.as_u64().unwrap() as u8)
                    .collect();
                fs::write(&target, &payload).unwrap();
                let got = summary(&target, &root).unwrap();
                assert_eq!(got, case["expected"], "case {name}");
                assert_eq!(
                    got["sha256"].as_str().unwrap(),
                    case["input"]["digest"].as_str().unwrap(),
                    "case {name}: digest"
                );
                let _ = fs::remove_dir_all(&root);
            }
            other => panic!("unknown gold case kind {other}"),
        }
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}
